/*
 * Benchmarks pages: scoreboard, run dossier, head-to-head and calibration.
 *
 * Data: window.faBench, generated by docs/generate_benchmark_data.py from
 * docs/benchmark_data (per-trial run files + catalog.json). Edit those, not
 * the generated file.
 *
 * Mount points (markdown pages under docs/benchmarks/):
 *   <div data-fa-bench="index">       scoreboard, frontier, task matrix, comparisons
 *   <div data-fa-bench="run">         dossier for ?id=<run id>
 *   <div data-fa-bench="compare">     head-to-head for ?c=<comparison> or ?a=&b=
 *   <div data-fa-bench="calibration" data-bench="tb4">  subset calibration chart
 *
 * Loaded on demand by benchmarks-loader.js, only on pages with a mount point.
 */
(function () {
  "use strict";

  var SVGNS = "http://www.w3.org/2000/svg";
  var SITE_ROOT = (function () {
    var script = document.currentScript;
    return script ? script.src.replace(/javascripts\/benchmarks\.js.*$/, "") : "/";
  })();
  var BENCH_ROOT = SITE_ROOT + "benchmarks/";
  var MARKS = SITE_ROOT + "assets/forward/assets/providers/";
  var ATIF_SCAN_URL = "https://github.com/evalstate/atif-scan";

  /* Cell codes, bottom-to-top stacking order inside a task column. */
  var CELL_ORDER = { "1": 0, x: 1, "0": 2, t: 3, e: 4, "-": 5 };
  var CELL_LABEL = {
    "1": "pass",
    x: "pass, disqualified by the leaderboard judge",
    "0": "fail",
    t: "agent timeout",
    e: "error",
    "-": "missing",
  };

  /* ── Small DOM helpers ─────────────────────────────────────────────── */
  function el(tag, cls, text) {
    var node = document.createElement(tag);
    if (cls) node.className = cls;
    if (text !== undefined && text !== null) node.textContent = text;
    return node;
  }
  function svg(tag, attrs, parent) {
    var node = document.createElementNS(SVGNS, tag);
    Object.keys(attrs || {}).forEach(function (key) {
      node.setAttribute(key, attrs[key]);
    });
    if (parent) parent.appendChild(node);
    return node;
  }
  function link(href, cls, text) {
    var a = el("a", cls, text);
    a.href = href;
    return a;
  }
  function external(href, text) {
    var a = link(href, "fb-ext", text + " ↗");
    a.target = "_blank";
    a.rel = "noopener";
    return a;
  }

  /* ── Formatting (round down, never up) ─────────────────────────────── */
  function floor1(x) {
    return Math.floor(x * 10 + 1e-9) / 10;
  }
  function pct(x) {
    return floor1(x).toFixed(1) + "%";
  }
  function pts(x) {
    var v = floor1(Math.abs(x)).toFixed(1);
    return (x >= 0 ? "+" : "−") + v + " pts";
  }
  function money(x) {
    if (x >= 1000) return "$" + Math.round(x).toLocaleString("en-GB");
    if (x >= 100) return "$" + x.toFixed(0);
    return "$" + x.toFixed(2);
  }
  function moneyExact(x) {
    return "$" + x.toFixed(2);
  }
  function costText(entry, exact) {
    var text = (exact ? moneyExact : money)(entry.cost.total);
    return entry.cost.estimate ? "~" + text : text;
  }
  function tokens(n) {
    if (n === null || n === undefined) return "—";
    if (n >= 1e9) return (n / 1e9).toFixed(2) + "B";
    if (n >= 1e6) return (n / 1e6).toFixed(1) + "M";
    return (n / 1e3).toFixed(0) + "K";
  }
  function date(iso) {
    var d = new Date(iso + "T00:00:00Z");
    return d.toLocaleDateString("en-GB", { day: "numeric", month: "short", year: "numeric", timeZone: "UTC" });
  }
  /* "NonZeroAgentExitCodeError" → "non-zero exits"; "AgentTimeoutError" → "timeouts". */
  var ERROR_NAMES = {
    AgentTimeoutError: "timeout",
    AgentSetupTimeoutError: "setup timeout",
    NonZeroAgentExitCodeError: "non-zero exit",
    VerifierTimeoutError: "verifier timeout",
  };
  function errorName(type, count) {
    var name =
      ERROR_NAMES[type] ||
      type
        .replace(/Error$/, "")
        .replace(/([a-z])([A-Z])/g, "$1 $2")
        .toLowerCase();
    return count === 1 ? name : name + "s";
  }
  function familyName(f) {
    return f.name.indexOf(f.maker) === 0 ? f.name : f.maker + " " + f.name;
  }
  function title(entry) {
    return entry.model + " · " + entry.effort;
  }
  function harnessLine(entry) {
    if (entry.tier === "claim") return entry.source + " · " + entry.title;
    return entry.harnessVersion ? entry.harness + " " + entry.harnessVersion : entry.harness;
  }

  /* ── Data model ────────────────────────────────────────────────────── */
  function taskOrder(tasks, difficulty) {
    // Easiest task first; ties broken by name so every chart shares one order.
    return tasks
      .map(function (t, i) {
        return i;
      })
      .sort(function (a, b) {
        return difficulty[b] - difficulty[a] || (tasks[a] < tasks[b] ? -1 : 1);
      });
  }

  /* One view of the data per benchmark; byId spans every benchmark. */
  function model(data, benchId) {
    var byId = {};
    var families = {};
    data.families.forEach(function (f) {
      families[f.id] = f;
    });
    data.runs.concat(data.claims).forEach(function (e) {
      byId[e.id] = e;
    });
    var bench =
      data.benchmarks.filter(function (b) {
        return b.id === benchId || b.slug === benchId;
      })[0] || data.benchmarks[0];
    if (!bench.tasks) return { bench: bench }; // announced, no data yet
    var mine = function (e) {
      return e.benchmark === bench.id;
    };
    var full = bench.full ? { tasks: bench.full.tasks, difficulty: bench.full.difficulty, order: taskOrder(bench.full.tasks, bench.full.difficulty) } : null;
    return {
      data: data,
      bench: bench,
      byId: byId,
      families: families,
      tasks: bench.tasks,
      attempts: bench.attempts,
      difficulty: bench.difficulty,
      order: taskOrder(bench.tasks, bench.difficulty),
      full: full,
      runs: data.runs.filter(mine),
      claims: data.claims.filter(mine),
      comparisons: data.comparisons.filter(mine),
      trialsPerRun: bench.tasks.length * bench.attempts,
    };
  }
  /* The same view restricted to the full task set (for runs that have one). */
  function fullModel(m) {
    return Object.assign({}, m, {
      tasks: m.full.tasks,
      difficulty: m.full.difficulty,
      order: m.full.order,
      runs: m.runs.filter(function (r) {
        return r.full;
      }).map(function (r) {
        return Object.assign({}, r, r.full, { tier: r.tier, id: r.id });
      }),
      trialsPerRun: m.full.tasks.length * m.attempts,
    });
  }

  function taskCells(run, index, attempts) {
    return run.cells.substr(index * attempts, attempts);
  }
  function taskPasses(run, index, attempts) {
    var cells = taskCells(run, index, attempts);
    var n = 0;
    for (var i = 0; i < cells.length; i++) if (cells[i] === "1") n++;
    return n;
  }
  function stacked(cells) {
    return cells.split("").sort(function (a, b) {
      return CELL_ORDER[a] - CELL_ORDER[b];
    });
  }

  /* ── atif-scan marks ───────────────────────────────────────────────
     run.scan.cells has one code per trial, aligned with run.cells:
     c/h/m/l = highest finding priority, upper case = the trial used another
     model (fallback), ? = no scan result. Every view marks attempts the same
     way: an orange corner on a high/critical attempt, a slash on a fallback
     attempt; strips too small for corners add a marker above the column. */
  function isFlagged(code) {
    return code === "c" || code === "h" || code === "C" || code === "H";
  }
  function isFallback(code) {
    return code === "C" || code === "H" || code === "M" || code === "L";
  }
  /* A task's attempts with their scan codes, in stacking order (passes first,
     flagged passes on top of clean ones). */
  function attemptsOf(run, index, attempts) {
    var cells = taskCells(run, index, attempts);
    var scan = run.scan ? run.scan.cells.substr(index * attempts, attempts) : "";
    return cells
      .split("")
      .map(function (c, i) {
        return { c: c, s: scan.charAt(i) };
      })
      .sort(function (a, b) {
        return CELL_ORDER[a.c] - CELL_ORDER[b.c] || isFlagged(a.s) - isFlagged(b.s) || isFallback(a.s) - isFallback(b.s);
      });
  }
  function cellClass(code) {
    return "fb-c fb-c--" + (code === "-" ? "m" : code);
  }
  /* Draw one attempt into an SVG; corner marks need cells of at least minCorner px. */
  function drawAttempt(parent, x, y, w, h, att, cls, minCorner) {
    svg("rect", { x: x, y: y, width: w, height: h, rx: w > 6 ? 1.5 : 0.8, class: cls }, parent);
    if (isFallback(att.s)) {
      svg("line", { x1: x + 0.5, y1: y + h - 0.5, x2: x + w - 0.5, y2: y + 0.5, class: "fb-fallback" }, parent);
    }
    if (isFlagged(att.s) && w >= minCorner) {
      var k = Math.min(w, h) * 0.55;
      svg("path", { d: "M" + (x + w - k) + " " + y + "h" + k + "v" + k + "z", class: "fb-flag" }, parent);
    }
  }
  /* Plain-language atif-scan summary of a task's attempts for tooltips. */
  function scanLines(run, index, attempts) {
    if (run.tier === "claim" || run.sample) return [];
    if (!run.scan) return ["atif-scan: this run hasn't been scanned"];
    var list = attemptsOf(run, index, attempts);
    var flagged = list.filter(function (a) { return isFlagged(a.s); });
    var passed = flagged.filter(function (a) { return a.c === "1" || a.c === "x"; }).length;
    var fallback = list.filter(function (a) { return isFallback(a.s); }).length;
    var medium = list.filter(function (a) { return a.s.toLowerCase() === "m"; }).length;
    var missing = list.filter(function (a) { return a.s === "?"; }).length;
    var lines = [];
    if (flagged.length) lines.push("atif-scan: " + plural(flagged.length, "attempt") + " with a high or critical finding (" + passed + " passed)");
    if (fallback) lines.push(plural(fallback, "attempt") + " ran on another model (fallback)");
    if (medium) lines.push("atif-scan: " + plural(medium, "attempt") + " with a medium finding");
    if (missing) lines.push("atif-scan: no result for " + plural(missing, "attempt"));
    if (!lines.length) lines.push("atif-scan: nothing above low priority");
    return lines;
  }
  function plural(n, word) {
    return n + " " + word + (n === 1 ? "" : "s");
  }
  function scanPresence(runs) {
    return {
      scanned: runs.some(function (r) { return r.scan; }),
      unscanned: runs.some(function (r) { return r.tier !== "claim" && !r.sample && !r.scan; }),
      flagged: runs.some(function (r) { return r.scan && /[chCH]/.test(r.scan.cells); }),
      fallback: runs.some(function (r) { return r.scan && /[CHML]/.test(r.scan.cells); }),
    };
  }

  /* ── Shared tooltip ────────────────────────────────────────────────── */
  var tip;
  function tooltip() {
    if (!tip || !document.body.contains(tip)) {
      tip = el("div", "fb-tip");
      tip.setAttribute("role", "tooltip");
      document.body.appendChild(tip);
    }
    return tip;
  }
  function showTip(evt, lines) {
    var t = tooltip();
    t.innerHTML = "";
    lines.forEach(function (line, i) {
      t.appendChild(el(i === 0 ? "strong" : "span", "", line));
    });
    t.style.display = "block";
    var x = evt.clientX + 14;
    var y = evt.clientY + 16;
    var w = t.offsetWidth;
    if (x + w > window.innerWidth - 8) x = evt.clientX - w - 14;
    t.style.left = x + "px";
    t.style.top = y + "px";
  }
  function hideTip() {
    if (tip) tip.style.display = "none";
  }

  /* ── Brand pieces ──────────────────────────────────────────────────── */
  function familyMark(m, familyId, size) {
    var f = m.families[familyId];
    var tile = el("span", "fb-mark fb-mark--" + familyId);
    if (size) tile.classList.add("fb-mark--" + size);
    var img = el("img");
    img.src = MARKS + f.mark;
    img.alt = f.maker;
    img.width = 20;
    img.height = 20;
    tile.appendChild(img);
    return tile;
  }
  function tierBadge(entry) {
    var label = { ours: "Our run", leaderboard: "Leaderboard", claim: "Vendor claim" }[entry.tier];
    return el("span", "fb-tier fb-tier--" + entry.tier, label);
  }
  function statusBadge(entry) {
    if (!entry.status) return null;
    var cls = entry.sample ? "fb-status fb-status--sample" : entry.timeout === "6h" ? "fb-status fb-status--timeout" : "fb-status";
    return el("span", cls, entry.status);
  }
  function runHref(id) {
    return BENCH_ROOT + "run/?id=" + encodeURIComponent(id);
  }
  function compareHref(a, b) {
    return BENCH_ROOT + "compare/?a=" + encodeURIComponent(a) + "&b=" + encodeURIComponent(b);
  }

  /* ── Task strip: 89 columns × 5 attempts, shared task order ────────── */
  /* Wide benchmarks (TB2.1, 89 tasks) get square 5px cells; small ones (TB4
     subset, 19–21 tasks) get wide bricks so the strip keeps the column width
     without making rows taller, and room for task labels in the header. */
  var STRIP_WIDTH = 560;
  function stripGeometry(cols) {
    if (cols > 40) return { cellW: 5, cellH: 5, gap: 1, colGap: 1, pitch: 6 };
    var pitch = Math.min(29, Math.floor(STRIP_WIDTH / cols));
    return { cellW: pitch - 3, cellH: 10, gap: 2, colGap: 3, pitch: pitch };
  }
  function taskHeader(m) {
    var geo = stripGeometry(m.order.length);
    var width = m.order.length * geo.pitch - geo.colGap;
    var height = 118;
    var root = svg("svg", { class: "fb-taskhead", viewBox: "0 0 " + width + " " + height, width: width, height: height, "aria-hidden": "true" });
    m.order.forEach(function (ti, col) {
      var x = col * geo.pitch + geo.cellW / 2;
      var t = svg("text", { x: 0, y: 0, transform: "translate(" + (x + 3) + " " + (height - 4) + ") rotate(-58)", class: "fb-taskhead__t" }, root);
      t.textContent = m.tasks[ti];
    });
    return root;
  }

  function taskStrip(m, run, opts) {
    opts = opts || {};
    var cols = m.order.length;
    var geo = stripGeometry(cols);
    var cell = geo.cellW;
    var cellH = geo.cellH;
    var gap = geo.gap;
    var colGap = geo.colGap;
    var flagRoom = opts.flags === false ? 0 : 5;
    var width = cols * (cell + colGap) - colGap;
    var height = flagRoom + m.attempts * (cellH + gap) - gap;
    var root = svg("svg", {
      class: "fb-strip fb-strip--" + run.tier,
      viewBox: "0 0 " + width + " " + height,
      width: width * (opts.scale || 1),
      height: height * (opts.scale || 1),
      role: "img",
      "aria-label": title(run) + " on " + run.harness + ": " + run.passes + " of " + run.slots + " trials passed",
    });
    m.order.forEach(function (taskIndex, col) {
      var x = col * (cell + colGap);
      var list = attemptsOf(run, taskIndex, m.attempts);
      list.forEach(function (att, row) {
        var y = flagRoom + (m.attempts - 1 - row) * (cellH + gap);
        drawAttempt(root, x, y, cell, cellH, att, cellClass(att.c), 8);
      });
      if (list.some(function (a) { return isFlagged(a.s); })) {
        var cx = x + cell / 2;
        svg("path", { d: "M" + (cx - 2.5) + " 0h5l-2.5 3.5z", class: "fb-flag" }, root);
      }
    });
    root.addEventListener("mousemove", function (evt) {
      var box = root.getBoundingClientRect();
      var col = Math.floor(((evt.clientX - box.left) / box.width) * cols);
      if (col < 0 || col >= cols) return hideTip();
      var taskIndex = m.order[col];
      var name = m.tasks[taskIndex];
      var cells = taskCells(run, taskIndex, m.attempts);
      var passes = taskPasses(run, taskIndex, m.attempts);
      var lines = [name, passes + " of " + m.attempts + " attempts passed"];
      var other = cells.replace(/[10]/g, "");
      if (other) {
        lines.push(
          other
            .split("")
            .map(function (c) {
              return CELL_LABEL[c];
            })
            .join(", ")
        );
      }
      lines = lines.concat(scanLines(run, taskIndex, m.attempts));
      lines.push("All runs: " + Math.round(m.difficulty[taskIndex] * 100) + "% of attempts pass");
      showTip(evt, lines);
    });
    root.addEventListener("mouseleave", hideTip);
    return root;
  }

  /* A claim has no trial data: a dashed frame the size of a strip, hatched to the score. */
  function claimStrip(m, claim, opts) {
    opts = opts || {};
    var geo = stripGeometry(m.order.length);
    var cell = opts.cell || geo.cellW;
    var colGap = opts.colGap || geo.colGap;
    var width = m.order.length * (cell + colGap) - colGap;
    var height = opts.height || 5 + m.attempts * (geo.cellH + geo.gap) - geo.gap;
    var root = svg("svg", {
      class: "fb-strip fb-strip--claim",
      viewBox: "0 0 " + width + " " + height,
      width: width * (opts.scale || 1),
      height: height * (opts.scale || 1),
      role: "img",
      "aria-label": claim.source + " reports " + claim.score + "%; no trial data published",
    });
    svg("rect", { x: 1, y: 6, width: width - 2, height: height - 7, rx: 2, class: "fb-claim-frame" }, root);
    svg("rect", { x: 1, y: 6, width: (width - 2) * (claim.score / 100), height: height - 7, rx: 2, class: "fb-claim-fill" }, root);
    var label = svg("text", { x: 8, y: 6 + (height - 6) / 2 + 3.5, class: "fb-claim-label" }, root);
    label.textContent = "No trial data published · score only";
    return root;
  }

  /* ── Log cost axis ─────────────────────────────────────────────────── */
  /* Log cost domain padded to whole 1-2-5 steps around the entries' costs. */
  function costDomain(entries) {
    var costs = entries.map(function (e) {
      return e.cost.total;
    });
    var steps = [];
    for (var k = -1; k < 5; k++) [1, 2, 5].forEach(function (f) { steps.push(f * Math.pow(10, k)); });
    var lo = Math.min.apply(null, costs);
    var hi = Math.max.apply(null, costs);
    var min = steps.filter(function (v) { return v <= lo * 0.85; }).pop() || steps[0];
    var max = steps.filter(function (v) { return v >= hi * 1.15; })[0] || steps[steps.length - 1];
    var ticks = steps.filter(function (v) { return v > min && v < max; });
    while (ticks.length > 4) ticks = ticks.filter(function (_, i) { return i % 2 === 1; });
    return { min: min, max: max, ticks: ticks, all: steps.filter(function (v) { return v >= min && v <= max; }) };
  }
  function costX(cost, width, dom) {
    var c = Math.max(dom.min, Math.min(dom.max, cost));
    return (Math.log(c / dom.min) / Math.log(dom.max / dom.min)) * width;
  }
  function costDot(entry, width, dom) {
    var h = 28;
    var root = svg("svg", { class: "fb-costdot", viewBox: "0 0 " + width + " " + h, width: "100%", height: h, preserveAspectRatio: "none", "aria-hidden": "true" });
    dom.ticks.forEach(function (t) {
      var x = costX(t, width, dom);
      svg("line", { x1: x, x2: x, y1: 2, y2: h - 2, class: "fb-grid" }, root);
    });
    svg("line", { x1: 0, x2: width, y1: h / 2, y2: h / 2, class: "fb-track" }, root);
    var x = costX(entry.cost.total, width, dom);
    if (entry.tier === "ours" && entry.cost.recorded !== entry.cost.total && entry.cost.pricing) {
      var ox = costX(entry.cost.recorded, width, dom);
      svg("line", { x1: ox, x2: x, y1: h / 2, y2: h / 2, class: "fb-reprice" }, root);
      svg("circle", { cx: ox, cy: h / 2, r: 4, class: "fb-dot fb-dot--was" }, root);
    }
    svg("circle", { cx: x, cy: h / 2, r: 6, class: "fb-dot fb-dot--" + entry.tier }, root);
    return root;
  }
  function costAxis(width, dom) {
    var root = svg("svg", { class: "fb-costaxis", viewBox: "0 0 " + width + " 16", width: "100%", height: 16, preserveAspectRatio: "none", "aria-hidden": "true" });
    dom.ticks.forEach(function (t) {
      var text = svg("text", { x: costX(t, width, dom), y: 12, "text-anchor": "middle" }, root);
      text.textContent = t >= 1000 ? "$" + t / 1000 + "k" : "$" + t;
    });
    return root;
  }

  /* ── Scoreboard (Direction A: the ledger) ──────────────────────────── */
  function scoreboard(m, state) {
    var wrap = el("div", "fb-board");

    var controls = el("div", "fb-controls");
    var families = el("div", "fb-chips");
    families.setAttribute("role", "group");
    families.setAttribute("aria-label", "Model family");
    [{ id: "all", name: "All models" }].concat(m.data.families).forEach(function (f) {
      var count = m.runs.concat(m.claims).filter(function (e) {
        return f.id === "all" || e.family === f.id;
      }).length;
      if (!count) return;
      var chip = el("button", "fb-chip");
      chip.type = "button";
      if (f.id !== "all") chip.appendChild(familyMark(m, f.id, "sm"));
      chip.appendChild(el("span", "", f.id === "all" ? f.name : familyName(f)));
      chip.appendChild(el("span", "fb-chip__n", String(count)));
      chip.setAttribute("aria-pressed", String(state.family === f.id));
      chip.addEventListener("click", function () {
        state.family = f.id;
        state.redraw();
      });
      families.appendChild(chip);
    });
    controls.appendChild(families);

    var toggles = el("div", "fb-toggles");
    function toggle(key, label) {
      var lab = el("label", "fb-toggle");
      var input = el("input");
      input.type = "checkbox";
      input.checked = state[key];
      input.addEventListener("change", function () {
        state[key] = input.checked;
        state.redraw();
      });
      lab.appendChild(input);
      lab.appendChild(el("span", "", label));
      return lab;
    }
    toggles.appendChild(toggle("leaderboard", "Leaderboard runs"));
    if (m.claims.length) toggles.appendChild(toggle("claims", "Vendor claims"));
    if (m.runs.some(function (r) { return r.timeout === "6h"; })) toggles.appendChild(toggle("long", "Six-hour runs"));
    var sort = el("div", "fb-seg");
    sort.setAttribute("role", "group");
    sort.setAttribute("aria-label", "Order");
    [
      ["family", "By family"],
      ["score", "By score"],
      ["cost", "By cost"],
    ].forEach(function (opt) {
      var b = el("button", "", opt[1]);
      b.type = "button";
      b.setAttribute("aria-pressed", String(state.sort === opt[0]));
      b.addEventListener("click", function () {
        state.sort = opt[0];
        state.redraw();
      });
      sort.appendChild(b);
    });
    toggles.appendChild(sort);
    controls.appendChild(toggles);
    wrap.appendChild(controls);

    var entries = m.runs.concat(m.claims).filter(function (e) {
      if (state.family !== "all" && e.family !== state.family) return false;
      if (e.tier === "leaderboard" && !state.leaderboard) return false;
      if (e.tier === "claim" && !state.claims) return false;
      if (e.timeout === "6h" && !state.long) return false;
      return true;
    });
    var byScore = function (a, b) {
      if (state.sort === "family") return (b.tier === "ours") - (a.tier === "ours") || b.score - a.score;
      return b.score - a.score;
    };
    entries.sort(
      state.sort === "cost"
        ? function (a, b) {
            return a.cost.total - b.cost.total;
          }
        : byScore
    );

    var table = el("div", "fb-ledger");
    table.setAttribute("role", "table");
    table.setAttribute("aria-label", "Terminal-Bench 2.1 results");
    var head = el("div", "fb-ledger__head");
    head.setAttribute("role", "row");
    head.appendChild(el("span", "fb-h", "Model · harness"));
    var th = el("span", "fb-h fb-h--tasks");
    th.appendChild(el("span", "", m.bench.taskLabel));
    th.appendChild(el("span", "fb-h__sub", "easiest → hardest across all runs"));
    if (m.order.length <= 40) {
      th.classList.add("fb-h--labelled");
      th.insertBefore(taskHeader(m), th.firstChild);
    }
    head.appendChild(th);
    head.appendChild(el("span", "fb-h fb-h--num", "Score"));
    var ch = el("span", "fb-h fb-h--cost");
    ch.appendChild(el("span", "", "Run cost"));
    var dom = costDomain(m.runs.concat(m.claims));
    ch.appendChild(costAxis(200, dom));
    head.appendChild(ch);
    table.appendChild(head);

    var scanned = scanPresence(m.runs).scanned;
    function row(entry) {
      var r = el(entry.tier === "claim" ? "div" : "a", "fb-row fb-row--" + entry.tier);
      r.setAttribute("role", "row");
      if (entry.tier !== "claim") r.href = runHref(entry.id);
      var who = el("span", "fb-who");
      who.appendChild(familyMark(m, entry.family));
      var names = el("span", "fb-names");
      names.appendChild(el("span", "fb-model", title(entry)));
      var meta = el("span", "fb-meta");
      meta.appendChild(tierBadge(entry));
      meta.appendChild(el("span", "fb-harness", harnessLine(entry)));
      var status = statusBadge(entry);
      if (status) meta.appendChild(status);
      if (scanned && entry.tier !== "claim" && !entry.sample && !entry.scan) meta.appendChild(el("span", "fb-noscan", "not scanned"));
      names.appendChild(meta);
      who.appendChild(names);
      r.appendChild(who);

      var strip = el("span", "fb-cell-strip");
      strip.appendChild(entry.tier === "claim" ? claimStrip(m, entry) : taskStrip(m, entry));
      r.appendChild(strip);

      var score = el("span", "fb-score");
      score.appendChild(el("span", "fb-score__v", pct(entry.score)));
      score.appendChild(el("span", "fb-score__n", entry.tier === "claim" ? "reported" : entry.passes + "/" + entry.slots + " · ±" + entry.se.toFixed(1)));
      if (m.full) {
        score.appendChild(
          el("span", "fb-score__full", entry.full ? "full run " + pct(entry.full.publishedScore) : "subset only")
        );
      }
      r.appendChild(score);

      var cost = el("span", "fb-cost");
      cost.appendChild(costDot(entry, 200, dom));
      var cv = el("span", "fb-cost__v", costText(entry));
      cost.appendChild(cv);
      r.appendChild(cost);
      return r;
    }

    if (state.sort === "family") {
      m.data.families.forEach(function (f) {
        var group = entries.filter(function (e) {
          return e.family === f.id;
        });
        if (!group.length) return;
        var gh = el("div", "fb-group");
        gh.appendChild(familyMark(m, f.id, "sm"));
        gh.appendChild(el("span", "fb-group__name", familyName(f)));
        var ours = group.filter(function (e) {
          return e.tier === "ours";
        }).length;
        gh.appendChild(el("span", "fb-group__n", ours ? ours + " of our runs" : "comparators only"));
        table.appendChild(gh);
        group.forEach(function (e) {
          table.appendChild(row(e));
        });
      });
    } else {
      entries.forEach(function (e) {
        table.appendChild(row(e));
      });
    }
    if (!entries.length) table.appendChild(el("p", "fb-empty", "No results match these filters."));
    wrap.appendChild(table);
    wrap.appendChild(legend(m.runs, m.claims.length > 0, true));
    return wrap;
  }

  /* One legend for every attempt view; scan items appear only when relevant. */
  function legend(runs, withClaim, columnMarks) {
    var lg = el("div", "fb-legend");
    var scan = scanPresence(runs);
    var tiers = {};
    runs.forEach(function (r) { tiers[r.tier] = true; });
    var dq = runs.some(function (r) { return r.cells && r.cells.indexOf("x") >= 0; });
    var errors = runs.some(function (r) { return r.cells && r.cells.indexOf("e") >= 0; });
    var timeouts = runs.some(function (r) { return r.cells && r.cells.indexOf("t") >= 0; });
    [
      tiers.ours && ["fb-sw fb-sw--ours", "our pass"],
      tiers.leaderboard && ["fb-sw fb-sw--leaderboard", "comparator pass"],
      ["fb-sw fb-sw--fail", "fail"],
      timeouts && ["fb-sw fb-sw--t", "timeout"],
      errors && ["fb-sw fb-sw--e", "error"],
      dq && ["fb-sw fb-sw--x", "judge DQ"],
      scan.flagged && ["fb-sw fb-sw--flag", "atif-scan: high or critical finding"],
      scan.flagged && columnMarks && ["fb-sw fb-sw--flagcol", "task has a flagged attempt"],
      scan.fallback && ["fb-sw fb-sw--fallback", "ran on another model"],
      scan.unscanned && scan.scanned && ["fb-sw fb-sw--noscan", "not scanned"],
      scan.unscanned && !scan.scanned && ["fb-sw fb-sw--noscan", "no atif-scan review yet"],
      withClaim && ["fb-sw fb-sw--claim", "vendor claim, no trials"],
    ]
      .filter(Boolean)
      .forEach(function (item) {
        var s = el("span", "fb-legend__i");
        s.appendChild(el("i", item[0]));
        s.appendChild(el("span", "", item[1]));
        lg.appendChild(s);
      });
    return lg;
  }

  /* ── Frontier: score vs run cost (log) ─────────────────────────────── */
  function frontier(m, opts) {
    opts = opts || {};
    var entries = (opts.entries || m.runs.concat(m.claims)).slice();
    var W = 960;
    var H = opts.height || 480;
    var pad = { l: 56, r: 24, t: 24, b: 48 };
    var iw = W - pad.l - pad.r;
    var ih = H - pad.t - pad.b;
    var scores = entries.map(function (e) {
      return e.score;
    });
    var sMin = Math.max(0, Math.floor((Math.min.apply(null, scores) - 4) / 4) * 4);
    var sMax = Math.min(100, Math.ceil((Math.max.apply(null, scores) + 4) / 4) * 4);
    var sStep = sMax - sMin > 32 ? 10 : 4;
    if (sStep === 10) {
      sMin = Math.floor(sMin / 10) * 10;
      sMax = Math.ceil(sMax / 10) * 10;
    }
    var dom = costDomain(entries);
    function X(c) {
      return pad.l + costX(c, iw, dom);
    }
    function Y(s) {
      return pad.t + (1 - (s - sMin) / (sMax - sMin)) * ih;
    }
    var root = svg("svg", { class: "fb-frontier", viewBox: "0 0 " + W + " " + H, role: "img", "aria-label": "Score against run cost for every run and claim" });
    // Cheap band — the one allowed flat tint.
    if (m.bench.cheapBand) {
      svg("rect", { x: pad.l, y: pad.t, width: X(m.bench.cheapBand) - pad.l, height: ih, class: "fb-band" }, root);
      var bandLabel = svg("text", { x: pad.l + 8, y: H - pad.b - 8, class: "fb-band__label" }, root);
      bandLabel.textContent = "UNDER $" + m.bench.cheapBand + " A RUN";
    }
    for (var s = sMin; s <= sMax; s += sStep) {
      svg("line", { x1: pad.l, x2: W - pad.r, y1: Y(s), y2: Y(s), class: "fb-grid" }, root);
      var t = svg("text", { x: pad.l - 10, y: Y(s) + 4, "text-anchor": "end", class: "fb-axis" }, root);
      t.textContent = s + "%";
    }
    dom.all.forEach(function (c) {
      svg("line", { x1: X(c), x2: X(c), y1: pad.t, y2: H - pad.b, class: "fb-grid fb-grid--v" }, root);
      var t = svg("text", { x: X(c), y: H - pad.b + 20, "text-anchor": "middle", class: "fb-axis" }, root);
      t.textContent = "$" + c.toLocaleString("en-GB");
    });
    var xl = svg("text", { x: W - pad.r, y: H - 6, "text-anchor": "end", class: "fb-axis fb-axis--title" }, root);
    xl.textContent = "cost per " + m.trialsPerRun + "-trial run (log scale) →";
    var yl = svg("text", { x: 12, y: pad.t - 8, class: "fb-axis fb-axis--title" }, root);
    yl.textContent = "↑ score";

    // Pareto frontier across runs with trial data.
    var withTrials = entries
      .filter(function (e) {
        return e.tier !== "claim";
      })
      .sort(function (a, b) {
        return a.cost.total - b.cost.total;
      });
    var best = -1;
    var pts = [];
    withTrials.forEach(function (e) {
      if (e.score > best) {
        best = e.score;
        pts.push(e);
      }
    });
    if (pts.length > 1) {
      var d = pts
        .map(function (e, i) {
          return (i ? "L" : "M") + X(e.cost.total).toFixed(1) + " " + Y(e.score).toFixed(1);
        })
        .join(" ");
      svg("path", { d: d, class: "fb-pareto" }, root);
    }

    // Claim → our run connectors.
    entries.forEach(function (e) {
      if (e.tier !== "claim" || !e.pairsWith || !m.byId[e.pairsWith]) return;
      var o = m.byId[e.pairsWith];
      if (entries.indexOf(o) < 0) return;
      svg("line", { x1: X(e.cost.total), y1: Y(e.score), x2: X(o.cost.total), y2: Y(o.score), class: "fb-pairline" }, root);
    });

    // Reserve every marker first so labels never sit on a point.
    var placed = entries.map(function (e) {
      var cx = X(e.cost.total);
      var cy = Y(e.score);
      return [cx - 10, cy - 8, cx + 10, cy + 8];
    });
    var order = entries.slice().sort(function (a, b) {
      return (a.tier === "ours") - (b.tier === "ours");
    });
    // Crowded charts label our runs, claims, the frontier and same-model comparators; the rest keep tooltips.
    var ourModels = entries.filter(function (e) { return e.tier === "ours"; }).map(function (e) { return e.model + e.effort; });
    function labelled(e) {
      return entries.length <= 20 || e.tier !== "leaderboard" || pts.indexOf(e) >= 0 || ourModels.indexOf(e.model + e.effort) >= 0;
    }
    function attachTip(g, e) {
      g.addEventListener("mousemove", function (evt) {
        showTip(evt, [title(e), harnessLine(e), pct(e.score) + (e.tier === "claim" ? " reported" : " · " + e.passes + "/" + e.slots), costText(e, true) + " per run" + (e.cost.basis ? " · " + e.cost.basis : "")]);
      });
      g.addEventListener("mouseleave", hideTip);
      if (e.tier !== "claim") {
        g.addEventListener("click", function () {
          window.location.href = runHref(e.id);
        });
      }
    }
    order.forEach(function (e) {
      var cx = X(e.cost.total);
      var cy = Y(e.score);
      var g = svg("g", { class: "fb-pt fb-pt--" + e.tier, tabindex: "0" }, root);
      if (e.tier !== "claim") {
        var top = Math.max(pad.t, Y(e.score + 1.96 * e.se));
        var bottom = Math.min(H - pad.b, Y(e.score - 1.96 * e.se));
        svg("line", { x1: cx, x2: cx, y1: bottom, y2: top, class: "fb-ci" }, g);
      }
      var at = svg("g", { transform: "translate(" + cx + " " + cy + ")" }, g);
      if (e.tier === "ours") {
        svg("rect", { x: -9, y: -5.5, width: 18, height: 11, rx: 5.5, class: "fb-marker fb-marker--capsule" }, at);
      } else {
        svg("circle", { cx: 0, cy: 0, r: 6, class: "fb-marker" }, at);
      }
      if (!labelled(e)) {
        attachTip(g, e);
        return;
      }
      // Label placement: try right, left, above, below; avoid markers and earlier labels.
      var text = (e.tier === "ours" ? "" : e.tier === "claim" ? e.source + ": " : e.harness + ": ") + e.model.replace("GPT-5.6 ", "") + " " + e.effort;
      var w = text.length * 6.6;
      var cands = [
        [cx + 13, cy + 4, "start"],
        [cx - 13, cy + 4, "end"],
        [cx, cy - 12, "middle"],
        [cx, cy + 22, "middle"],
        [cx + 13, cy - 10, "start"],
        [cx + 13, cy + 18, "start"],
      ];
      // First spot clear of everything; else the first spot inside the plot.
      var chosen = null;
      var fallback = null;
      cands.forEach(function (c) {
        if (chosen) return;
        var x0 = c[2] === "start" ? c[0] : c[2] === "end" ? c[0] - w : c[0] - w / 2;
        var box = [x0, c[1] - 11, x0 + w, c[1] + 3];
        if (x0 < pad.l || box[2] > W - 4) return;
        if (!fallback) fallback = [c, box];
        var hit = placed.some(function (p) {
          return !(box[2] < p[0] || box[0] > p[2] || box[3] < p[1] || box[1] > p[3]);
        });
        if (!hit) chosen = [c, box];
      });
      chosen = chosen || fallback || [cands[1], [0, 0, 0, 0]];
      placed.push(chosen[1]);
      chosen = chosen[0];
      var label = svg("text", { x: chosen[0], y: chosen[1], "text-anchor": chosen[2], class: "fb-pt__label" }, g);
      label.textContent = text;
      attachTip(g, e);
    });
    var fig = el("figure", "fb-figure");
    fig.appendChild(root);
    var cap = el("figcaption", "fb-caption");
    cap.textContent =
      "Capsules: our runs · dots: leaderboard runs · dashed rings: vendor claims (no trials) · whiskers: 95% interval, clustered by task · line: best score at or below each cost.";
    fig.appendChild(cap);
    return fig;
  }

  /* ── Task matrix (Direction B) ─────────────────────────────────────── */
  function matrix(m, opts) {
    opts = opts || {};
    var runs = (opts.runs || m.runs).slice().sort(function (a, b) {
      return b.score - a.score;
    });
    var cols = m.order.length;
    var cellW = opts.cell || (cols > 40 ? 9 : 30);
    var cell = opts.cell || 9;
    var labelW = 210;
    var W = labelW + cols * cellW;
    var headH = 12;
    var H = headH + runs.length * (cell + 3);
    var root = svg("svg", { class: "fb-matrix", viewBox: "0 0 " + W + " " + H, role: "img", "aria-label": "Pass rate per task for every run" });
    // Difficulty header.
    m.order.forEach(function (ti, col) {
      var d = m.difficulty[ti];
      svg("rect", { x: labelW + col * cellW, y: 8 - d * 8, width: cellW - 1, height: Math.max(0.6, d * 8), class: "fb-diff" }, root);
    });
    runs.forEach(function (r, row) {
      var y = headH + row * (cell + 3);
      var g = svg("g", { class: "fb-mrow fb-mrow--" + r.tier }, root);
      var label = svg("text", { x: labelW - 10, y: y + cell - 1, "text-anchor": "end", class: "fb-mrow__label" }, g);
      label.textContent = (r.tier === "ours" ? "" : r.harness + " · ") + title(r) + (r.sample ? " (sample)" : "");
      if (r.tier === "ours") svg("rect", { x: labelW - 6, y: y, width: 3, height: cell, class: "fb-mrow__ours" }, g);
      m.order.forEach(function (ti, col) {
        var p = taskPasses(r, ti, m.attempts);
        svg("rect", { x: labelW + col * cellW, y: y, width: cellW - 1, height: cell, class: "fb-m fb-m--" + p }, g);
      });
      g.addEventListener("mousemove", function (evt) {
        var box = root.getBoundingClientRect();
        var sx = ((evt.clientX - box.left) / box.width) * W;
        var col = Math.floor((sx - labelW) / cellW);
        if (col < 0 || col >= m.order.length) return hideTip();
        var ti = m.order[col];
        showTip(evt, [m.tasks[ti], harnessLine(r) + " · " + title(r), taskPasses(r, ti, m.attempts) + " of 5 passed"]);
      });
      g.addEventListener("mouseleave", hideTip);
      g.addEventListener("click", function () {
        window.location.href = runHref(r.id);
      });
    });
    var fig = el("figure", "fb-figure fb-figure--matrix");
    var scroller = el("div", "fb-scroll");
    scroller.appendChild(root);
    fig.appendChild(scroller);
    var key = el("figcaption", "fb-caption fb-caption--ramp");
    key.appendChild(el("span", "", "Attempts passed per task:"));
    for (var i = 0; i <= 5; i++) {
      var k = el("span", "fb-ramp");
      k.appendChild(el("i", "fb-m--" + i));
      k.appendChild(el("span", "", String(i)));
      key.appendChild(k);
    }
    key.appendChild(el("span", "", "· columns ordered by pass rate across all runs; bars above show it."));
    fig.appendChild(key);
    return fig;
  }

  /* ── Index page ────────────────────────────────────────────────────── */
  function benchParam() {
    return new URLSearchParams(window.location.search).get("b");
  }

  function renderIndex(root, data) {
    var intro = el("section", "fb-intro");
    var copy = el("div", "fb-intro__copy");
    copy.appendChild(el("p", "fb-kicker", "Benchmarks · updated " + date(data.updated)));
    copy.appendChild(el("h1", "", "Benchmarks and Comparisons"));
    copy.appendChild(
      el(
        "p",
        "fb-lede",
        "Results are drawn trial by trial. Hover any column for the task; open a run for its jobs, costs and atif-scan review."
      )
    );
    intro.appendChild(copy);
    root.appendChild(intro);

    var tabs = el("nav", "fb-bench-tabs");
    tabs.setAttribute("aria-label", "Benchmark");
    var slot = el("div", "fb-bench-slot");
    function show(slug, push) {
      var m = model(data, slug);
      tabs.querySelectorAll("button").forEach(function (b) {
        b.setAttribute("aria-pressed", String(b.dataset.slug === m.bench.slug));
      });
      if (push) {
        var url = new URL(window.location.href);
        url.searchParams.set("b", m.bench.slug);
        window.history.replaceState(window.history.state, "", url);
      }
      slot.innerHTML = "";
      if (m.bench.comingSoon) renderComingSoon(slot, m.bench);
      else renderBench(slot, m);
    }
    data.benchmarks.forEach(function (b) {
      var ours = data.runs.filter(function (r) {
        return r.benchmark === b.id && r.tier === "ours";
      }).length;
      var total = data.runs.filter(function (r) {
        return r.benchmark === b.id;
      }).length;
      var btn = el("button", "fb-bench-tab");
      btn.type = "button";
      btn.dataset.slug = b.slug;
      btn.appendChild(el("span", "fb-bench-tab__name", b.short));
      btn.appendChild(el("span", "fb-bench-tab__meta", b.comingSoon ? "Coming soon" : b.taskLabel));
      btn.addEventListener("click", function () {
        show(b.slug, true);
      });
      tabs.appendChild(btn);
    });
    root.appendChild(tabs);
    root.appendChild(slot);
    show(benchParam(), false);
  }

  /* The tab names the benchmark; the head carries its blurb and leaderboard link. */
  function benchHead(bench, note) {
    var head = el("div", "fb-bench-head");
    head.appendChild(el("p", "", note ? bench.blurb + " " + note : bench.blurb));
    if (bench.url) head.appendChild(external(bench.url, "Leaderboard"));
    return head;
  }

  /* Announced benchmark: what it is, and the methodology if written; results to follow. */
  function renderComingSoon(root, bench) {
    root.appendChild(benchHead(bench));
    root.appendChild(el("div", "fb-soon", "Results coming soon."));
    if (bench.methodology) root.appendChild(methodologySummary({ bench: bench }));
  }

  function renderBench(root, m) {
    root.appendChild(benchHead(m.bench, "Each square is one attempt. Our passes are amber, other harnesses' are dark blue; a column is one task, easiest on the left. Click on a run for more detail."));
    if (m.runs.some(function (r) { return r.sample; })) root.appendChild(sampleBanner());

    var state = { family: "all", leaderboard: true, claims: true, long: true, sort: "family" };
    var boardSlot = el("div");
    state.redraw = function () {
      boardSlot.innerHTML = "";
      boardSlot.appendChild(scoreboard(m, state));
    };
    root.appendChild(boardSlot);
    state.redraw();

    root.appendChild(sectionHead("", "Score / Cost Chart", "Higher and further left is better. The cost scale is logarithmic."));
    root.appendChild(frontier(m));

    root.appendChild(sectionHead("", "Task Difficulty.", "One row per run, one column per task, darker is more attempts passed. Hard tasks sit on the right."));
    root.appendChild(matrix(m));

    root.appendChild(methodologySummary(m));
  }

  /* Per-benchmark fine print: key points from the catalog and a link to the full page. */
  function methodologySummary(m) {
    var meth = m.bench.methodology;
    var box = el("section", "fb-method");
    box.setAttribute("aria-labelledby", "fb-method-" + m.bench.slug);
    var head = el("header", "fb-section");
    head.appendChild(el("p", "fb-kicker", "Methodology"));
    var h = el("h2", "", meth.title);
    h.id = "fb-method-" + m.bench.slug;
    head.appendChild(h);
    box.appendChild(head);
    var grid = el("div", "fb-fine");
    meth.points.forEach(function (pt) {
      var d = el("div");
      d.appendChild(el("h3", "", pt.title));
      d.appendChild(el("p", "", pt.text));
      grid.appendChild(d);
    });
    box.appendChild(grid);
    var more = link(BENCH_ROOT + meth.page, "fb-method__more", "Read the full " + m.bench.short + " methodology →");
    box.appendChild(more);
    return box;
  }

  function sampleBanner() {
    var b = el("div", "fb-sample-banner");
    b.appendChild(el("strong", "", "Sample data."));
    b.appendChild(
      el("span", "", " Rows marked SAMPLE are synthesised from leaderboard rows to review the layout. They are not results and will be replaced by real runs.")
    );
    return b;
  }

  function ranks(values) {
    var idx = values.map(function (v, i) { return i; }).sort(function (a, b) { return values[a] - values[b]; });
    var r = new Array(values.length);
    for (var i = 0; i < idx.length; ) {
      var j = i;
      while (j + 1 < idx.length && values[idx[j + 1]] === values[idx[i]]) j++;
      for (var k = i; k <= j; k++) r[idx[k]] = (i + j) / 2;
      i = j + 1;
    }
    return r;
  }
  /* Leaderboard rows whose trial records reproduce the published score. */
  function calibrationRuns(m) {
    return m.runs.filter(function (r) {
      return r.full && r.reconciled;
    });
  }
  /* Agreement between subset and published full-run scores. */
  function subsetStats(runs) {
    var a = ranks(runs.map(function (r) { return r.score; }));
    var b = ranks(runs.map(function (r) { return r.full.publishedScore; }));
    var n = runs.length;
    var ma = a.reduce(function (x, y) { return x + y; }, 0) / n;
    var mb = b.reduce(function (x, y) { return x + y; }, 0) / n;
    var cov = 0, va = 0, vb = 0;
    for (var i = 0; i < n; i++) {
      cov += (a[i] - ma) * (b[i] - mb);
      va += (a[i] - ma) * (a[i] - ma);
      vb += (b[i] - mb) * (b[i] - mb);
    }
    var gaps = runs.map(function (r) { return Math.abs(r.score - r.full.publishedScore); });
    return {
      within5: gaps.filter(function (g) { return g <= 5; }).length,
      within10: gaps.filter(function (g) { return g <= 10; }).length,
      meanGap: gaps.reduce(function (x, y) { return x + y; }, 0) / n,
      spearman: cov / Math.sqrt(va * vb),
    };
  }

  /* Subset score against the full-run score for every run with both. */
  function calibration(m, opts) {
    opts = opts || {};
    var runs = calibrationRuns(m);
    var W = opts.width || 960;
    var H = opts.height || 440;
    var pad = { l: 56, r: 24, t: 20, b: 48 };
    var iw = W - pad.l - pad.r;
    var ih = H - pad.t - pad.b;
    var all = runs.map(function (r) { return r.full.publishedScore; }).concat(runs.map(function (r) { return r.score; }));
    var lo = Math.floor(Math.min.apply(null, all) / 10) * 10;
    var hi = Math.ceil(Math.max.apply(null, all) / 10) * 10;
    function X(v) { return pad.l + ((v - lo) / (hi - lo)) * iw; }
    function Y(v) { return pad.t + (1 - (v - lo) / (hi - lo)) * ih; }
    var root = svg("svg", { class: "fb-frontier fb-calib", viewBox: "0 0 " + W + " " + H, role: "img", "aria-label": "Subset score against full-run score" });
    svg("path", {
      d: "M" + X(lo) + " " + Y(lo + 5) + " L" + X(hi - 5) + " " + Y(hi) + " L" + X(hi) + " " + Y(hi) + " L" + X(hi) + " " + Y(hi - 5) + " L" + X(lo + 5) + " " + Y(lo) + " L" + X(lo) + " " + Y(lo) + " Z",
      class: "fb-band",
    }, root);
    for (var v = lo; v <= hi; v += 10) {
      svg("line", { x1: pad.l, x2: W - pad.r, y1: Y(v), y2: Y(v), class: "fb-grid" }, root);
      svg("line", { x1: X(v), x2: X(v), y1: pad.t, y2: H - pad.b, class: "fb-grid fb-grid--v" }, root);
      var ty = svg("text", { x: pad.l - 10, y: Y(v) + 4, "text-anchor": "end", class: "fb-axis" }, root);
      ty.textContent = v + "%";
      var tx = svg("text", { x: X(v), y: H - pad.b + 20, "text-anchor": "middle", class: "fb-axis" }, root);
      tx.textContent = v + "%";
    }
    svg("line", { x1: X(lo), y1: Y(lo), x2: X(hi), y2: Y(hi), class: "fb-diag" }, root);
    var at = lo + 0.72 * (hi - lo);
    var angle = (-Math.atan2(ih, iw) * 180) / Math.PI;
    var bl = svg("text", { x: 0, y: 0, "text-anchor": "middle", class: "fb-band__label", transform: "translate(" + X(at + 5) + " " + (Y(at) + 16) + ") rotate(" + angle + ")" }, root);
    bl.textContent = "WITHIN ±5 POINTS OF THE FULL RUN";
    var xl = svg("text", { x: W - pad.r, y: H - 6, "text-anchor": "end", class: "fb-axis fb-axis--title" }, root);
    xl.textContent = "published full-run score (" + m.full.tasks.length + " tasks) →";
    var yl = svg("text", { x: 12, y: pad.t - 6, class: "fb-axis fb-axis--title" }, root);
    yl.textContent = "↑ subset score (" + m.tasks.length + " tasks)";
    runs.forEach(function (r) {
      var gap = r.score - r.full.publishedScore;
      var g = svg("g", { class: "fb-pt fb-pt--leaderboard" + (Math.abs(gap) > 5 ? " fb-pt--off" : ""), tabindex: "0" }, root);
      var at = svg("g", { transform: "translate(" + X(r.full.publishedScore) + " " + Y(r.score) + ")" }, g);
      svg("circle", { cx: 0, cy: 0, r: 6, class: "fb-marker" }, at);
      g.addEventListener("mousemove", function (evt) {
        showTip(evt, [r.harness + " · " + title(r), "subset " + pct(r.score) + " · full " + pct(r.full.publishedScore), (gap >= 0 ? "+" : "−") + Math.abs(gap).toFixed(1) + " pts on the subset"]);
      });
      g.addEventListener("mouseleave", hideTip);
      g.addEventListener("click", function () {
        window.location.href = runHref(r.id);
      });
    });
    var fig = el("figure", "fb-figure");
    fig.appendChild(root);
    var st = subsetStats(runs);
    fig.appendChild(
      el(
        "figcaption",
        "fb-caption",
        st.within5 + " of " + runs.length + " leaderboard rows land inside the band and " + st.within10 + " within ±10 points; average gap " + st.meanGap.toFixed(2) + " points; rank correlation " + st.spearman.toFixed(2) + ". Orange rings are further out. Rows whose trial records don't reproduce the published score are left out."
      )
    );
    return fig;
  }

  function sectionHead(kicker, heading, body) {
    var h = el("header", "fb-section");
    h.appendChild(el("p", "fb-kicker", kicker));
    h.appendChild(el("h2", "", heading));
    if (body) h.appendChild(el("p", "", body));
    return h;
  }

  /* ── Run dossier ───────────────────────────────────────────────────── */
  function renderRun(root, data) {
    var id = new URLSearchParams(window.location.search).get("id") || data.runs[0].id;
    var run = model(data).byId[id];
    if (!run || run.tier === "claim") {
      root.appendChild(el("p", "fb-empty", "No run called “" + id + "”."));
      return;
    }
    var m = model(data, run.benchmark);
    root.appendChild(runPicker(m, run));

    var head = el("header", "fb-dossier__head");
    head.appendChild(familyMark(m, run.family, "lg"));
    var h = el("div", "fb-dossier__title");
    var meta = el("p", "fb-meta");
    meta.appendChild(tierBadge(run));
    meta.appendChild(el("span", "fb-harness", harnessLine(run) + " · " + date(run.date)));
    var status = statusBadge(run);
    if (status) meta.appendChild(status);
    h.appendChild(meta);
    h.appendChild(el("h1", "", title(run)));
    h.appendChild(el("p", "fb-mono", m.bench.name + " · " + run.modelString));
    head.appendChild(h);
    root.appendChild(head);
    if (run.sample) root.appendChild(sampleBanner());

    var kpis = el("div", "fb-kpis");
    function kpi(v, k, note, cls) {
      var d = el("div", "fb-kpi" + (cls ? " " + cls : ""));
      d.appendChild(el("span", "fb-kpi__v", v));
      d.appendChild(el("span", "fb-kpi__k", k));
      if (note) d.appendChild(el("span", "fb-kpi__n", note));
      kpis.appendChild(d);
    }
    kpi(pct(run.score), "score", "±" + run.se.toFixed(1) + " pts, one standard error by task", "fb-kpi--hero");
    var errors = run.errors ? Object.keys(run.errors) : [];
    kpi(
      run.passes + " / " + run.slots,
      "trials passed",
      run.errors
        ? errors.length
          ? errors.map(function (k) { return run.errors[k] + " " + errorName(k, run.errors[k]); }).join(" · ")
          : "no errors"
        : m.tasks.length + " tasks × " + m.attempts + " attempts"
    );
    kpi(costText(run, true), "run cost", run.cost.basis + (run.cost.pricing ? " · recorded " + moneyExact(run.cost.recorded) : ""));
    kpi(moneyExact(run.cost.total / Math.max(1, run.passes)), "per passed trial", run.perTrialCost ? "median trial " + moneyExact(run.perTrialCost.median) + " · p90 " + moneyExact(run.perTrialCost.p90) : moneyExact(run.cost.total / run.slots) + " per trial");
    if (run.tokens) kpi(tokens(run.tokens.input), "input tokens", tokens(run.tokens.cached) + " cached · " + tokens(run.tokens.output) + " out");
    else if (run.full) kpi(pct(run.full.publishedScore), "full run score", m.full.tasks.length + " tasks · " + money(run.full.cost) + " published cost");
    else kpi("—", "full run", "subset only");
    root.appendChild(kpis);

    root.appendChild(sectionHead("The wall", "All " + run.slots + " attempts.", "One tile per task, " + m.attempts + " attempts each. Hover for how every other run did on the same task."));
    root.appendChild(taskWall(m, run));

    if (run.full) {
      var fm = fullModel(m);
      var fr = fm.runs.filter(function (r) { return r.id === run.id; })[0];
      var gap = run.score - run.full.publishedScore;
      root.appendChild(
        sectionHead(
          "The full run",
          "All " + fm.tasks.length + " tasks.",
          "The leaderboard run behind this row: " + pct(run.full.publishedScore) + " on the full set against " + pct(run.score) + " on the subset (" + pts(gap) + "). Outlined tiles are the subset's " + m.tasks.length + " tasks."
        )
      );
      root.appendChild(taskWall(fm, fr, m.tasks));
    }

    root.appendChild(sectionHead("Receipts", "What atif-scan found.", null));
    root.appendChild(scanPanel(m, run));

    root.appendChild(sectionHead("Source data", "Download traces.", null));
    root.appendChild(sources(m, run));

    var same = m.runs.concat(m.claims).filter(function (e) {
      return e.id !== run.id && (e.family === run.family || e.pairsWith === run.id || (e.model === run.model && e.effort === run.effort));
    });
    if (same.length) {
      root.appendChild(sectionHead("Compare", "Set it against…", null));
      var list = el("div", "fb-against");
      same.forEach(function (e) {
        var a = link(compareHref(run.id, e.id), "fb-against__i");
        a.appendChild(familyMark(m, e.family, "sm"));
        a.appendChild(el("span", "", (e.tier === "claim" ? e.source : e.harness) + " · " + title(e)));
        a.appendChild(tierBadge(e));
        list.appendChild(a);
      });
      root.appendChild(list);
    }
  }

  function runPicker(m, current) {
    var bar = el("nav", "fb-picker");
    bar.setAttribute("aria-label", "Runs");
    bar.appendChild(link(BENCH_ROOT + "?b=" + m.bench.slug, "fb-back", "← All " + m.bench.short + " results"));
    var select = el("select", "fb-select");
    select.setAttribute("aria-label", "Choose a run");
    m.data.families.forEach(function (f) {
      var group = el("optgroup");
      group.label = familyName(f);
      m.runs
        .filter(function (r) {
          return r.family === f.id;
        })
        .forEach(function (r) {
          var o = el("option", "", (r.tier === "ours" ? "" : r.harness + " · ") + title(r) + (r.timeout === "6h" ? " (6h)" : "") + (r.sample ? " (sample)" : ""));
          o.value = r.id;
          o.selected = r.id === current.id;
          group.appendChild(o);
        });
      if (group.children.length) select.appendChild(group);
    });
    select.addEventListener("change", function () {
      window.location.href = runHref(select.value);
    });
    bar.appendChild(select);
    return bar;
  }

  function taskWall(m, run, highlight) {
    var wrap = el("div", "fb-wall-wrap");
    var controls = el("div", "fb-seg");
    var grid = el("div", "fb-wall");
    var sorts = {
      difficulty: function () {
        return m.order.slice();
      },
      result: function () {
        return m.order.slice().sort(function (a, b) {
          return taskPasses(run, b, m.attempts) - taskPasses(run, a, m.attempts);
        });
      },
      name: function () {
        return m.tasks.map(function (_, i) {
          return i;
        });
      },
    };
    function draw(kind) {
      grid.innerHTML = "";
      sorts[kind]().forEach(function (ti) {
        var name = m.tasks[ti];
        var cells = taskCells(run, ti, m.attempts);
        var p = taskPasses(run, ti, m.attempts);
        var tile = el("div", "fb-tile fb-tile--p" + p + (highlight && highlight.indexOf(name) >= 0 ? " fb-tile--subset" : ""));
        var squares = el("span", "fb-tile__cells");
        attemptsOf(run, ti, m.attempts).forEach(function (att) {
          var cls = "fb-c--" + (att.c === "-" ? "m" : att.c) + " fb-tier-" + run.tier;
          if (isFlagged(att.s)) cls += " is-flagged";
          if (isFallback(att.s)) cls += " is-fallback";
          squares.appendChild(el("i", cls));
        });
        tile.appendChild(squares);
        tile.appendChild(el("span", "fb-tile__name", name));
        tile.addEventListener("mousemove", function (evt) {
          var others = m.runs
            .filter(function (r) {
              return r.id !== run.id;
            })
            .map(function (r) {
              return taskPasses(r, ti, m.attempts);
            });
          var sum = others.reduce(function (a, b) {
            return a + b;
          }, 0);
          var lines = [name, p + " of " + m.attempts + " passed here"].concat(scanLines(run, ti, m.attempts));
          lines.push("Other " + others.length + " runs: " + sum + " of " + others.length * m.attempts + " attempts passed");
          showTip(evt, lines);
        });
        tile.addEventListener("mouseleave", hideTip);
        grid.appendChild(tile);
      });
    }
    [
      ["difficulty", "Easiest first"],
      ["result", "Best first"],
      ["name", "A–Z"],
    ].forEach(function (opt, i) {
      var b = el("button", "", opt[1]);
      b.type = "button";
      b.setAttribute("aria-pressed", String(i === 0));
      b.addEventListener("click", function () {
        controls.querySelectorAll("button").forEach(function (x) {
          x.setAttribute("aria-pressed", String(x === b));
        });
        draw(opt[0]);
      });
      controls.appendChild(b);
    });
    wrap.appendChild(controls);
    wrap.appendChild(grid);
    wrap.appendChild(legend([run], false));
    draw("difficulty");
    return wrap;
  }

  function scanPanel(m, run) {
    var s = run.scan;
    var box = el("div", "fb-scan");
    if (!s) {
      var none = el("div", "fb-scan__none");
      none.appendChild(
        el(
          "p",
          "",
          run.sample
            ? "Sample data has no trajectories to scan."
            : "No atif-scan review for this run yet. The run's trials are public; the Harbor job links below lead to them."
        )
      );
      box.appendChild(none);
      return box;
    }
    var head = el("div", "fb-scan__head");
    var hl = el("div");
    hl.appendChild(el("p", "fb-mono", "atif-scan " + s.version + " · " + s.trials + " trials scanned"));
    hl.appendChild(el("p", "fb-scan__lede", "Findings set review priority; they are not verdicts. Unknown evidence is never counted as clean."));
    head.appendChild(hl);
    head.appendChild(external(ATIF_SCAN_URL, "About atif-scan"));
    box.appendChild(head);

    var cols = el("div", "fb-scan__cols");

    // Review: the score if every high/critical rewarded trial were a failure.
    var review = el("section", "fb-scan__card fb-scan__card--review");
    review.appendChild(el("h3", "", "Review"));
    var big = el("p", "fb-scan__big", String(s.review.highRewarded));
    review.appendChild(big);
    review.appendChild(el("p", "", "rewarded trials with a high or critical finding"));
    if (s.review.scoreIfFlaggedFailed !== null) {
      var range = el("div", "fb-range");
      var lo = s.review.scoreIfFlaggedFailed;
      var hi = run.score;
      var scale = function (v) {
        return ((v - 60) / 40) * 100 + "%";
      };
      var track = el("div", "fb-range__track");
      var span = el("i", "fb-range__span");
      span.style.left = scale(lo);
      span.style.width = "calc(" + scale(hi) + " - " + scale(lo) + ")";
      track.appendChild(span);
      var a = el("b", "fb-range__lo");
      a.style.left = scale(lo);
      var b = el("b", "fb-range__hi");
      b.style.left = scale(hi);
      track.appendChild(a);
      track.appendChild(b);
      range.appendChild(track);
      var labels = el("div", "fb-range__labels");
      labels.appendChild(el("span", "", pct(lo) + " if every flagged trial failed"));
      labels.appendChild(el("span", "", pct(hi) + " recorded"));
      range.appendChild(labels);
      review.appendChild(range);
    }
    if (s.review.otherModelTrials) {
      review.appendChild(el("p", "fb-scan__warn", s.review.otherModelTrials + " rewarded trials used a model other than the one named (fallback). Counted as passes in the published score."));
    }
    if (s.review.incompleteRewarded) {
      review.appendChild(el("p", "fb-scan__note", s.review.incompleteRewarded + " rewarded trials can't be cleared: evidence incomplete."));
    }
    cols.appendChild(review);

    // Findings: the checks behind medium+ trials.
    var findings = el("section", "fb-scan__card");
    findings.appendChild(el("h3", "", "Findings"));
    findings.appendChild(el("p", "fb-scan__sub", s.findings.trials + " trials with a medium or higher finding, " + s.findings.rewarded + " of them rewarded"));
    var max = Math.max.apply(null, s.findings.top.map(function (f) { return f.trials; }).concat([1]));
    var list = el("ul", "fb-bars");
    s.findings.top.forEach(function (f) {
      var li = el("li", "fb-bars__i fb-pri--" + f.priority);
      var label = el("span", "fb-bars__label");
      label.appendChild(el("span", "fb-pri", f.priority));
      label.appendChild(el("span", "", f.title));
      li.appendChild(label);
      var bar = el("span", "fb-bars__bar");
      var fill = el("i");
      fill.style.width = (f.trials / max) * 100 + "%";
      bar.appendChild(fill);
      li.appendChild(bar);
      li.appendChild(el("span", "fb-bars__v", f.trials + (f.rewarded ? " · " + f.rewarded + " rewarded" : "")));
      li.title = f.check;
      list.appendChild(li);
    });
    findings.appendChild(list);
    cols.appendChild(findings);

    // Awareness funnel.
    var aw = el("section", "fb-scan__card");
    aw.appendChild(el("h3", "", "Benchmark awareness"));
    aw.appendChild(el("p", "fb-scan__sub", "Trials that worked out they were being tested, stage by stage"));
    var stages = s.awareness.stages;
    var names = { noticed: "remarked on a benchmark", named: "named one", recalled: "recalled its tasks", searched: "looked it up", obtained: "got material back" };
    var fmax = Math.max(1, stages.noticed ? stages.noticed.trials : 1);
    var funnel = el("ul", "fb-funnel");
    Object.keys(names).forEach(function (k) {
      var st = stages[k] || { trials: 0, rewarded: 0 };
      var li = el("li", "fb-funnel__i" + (k === "obtained" && st.trials ? " fb-funnel__i--hot" : ""));
      var bar = el("span", "fb-funnel__bar");
      bar.style.width = Math.max(2, (st.trials / fmax) * 100) + "%";
      li.appendChild(bar);
      li.appendChild(el("span", "fb-funnel__v", String(st.trials)));
      li.appendChild(el("span", "fb-funnel__k", names[k]));
      funnel.appendChild(li);
    });
    aw.appendChild(funnel);
    aw.appendChild(el("p", "fb-scan__note", s.awareness.verifier_talk.trials + " trials talked about tests or a verifier: ordinary work, not counted."));
    cols.appendChild(aw);

    // Evidence and cost.
    var ev = el("section", "fb-scan__card");
    ev.appendChild(el("h3", "", "Evidence"));
    var dl = el("dl", "fb-evidence");
    function row(k, v, warn) {
      var d = el("div", warn ? "is-warn" : "");
      d.appendChild(el("dt", "", k));
      d.appendChild(el("dd", "", v));
      dl.appendChild(d);
    }
    row("Trials present", s.evidence.planned - (s.evidence.without_trajectory || 0) + " of " + s.evidence.planned + " with traces", s.evidence.without_trajectory > 0);
    row("Errored", String(s.evidence.errored), s.evidence.errored > 0);
    row("Compacted history", String(s.evidence.compacted_history), s.evidence.compacted_history > 0);
    row("Trials without cost", String(s.cost.trials_missing_cost), s.cost.trials_missing_cost > 0);
    row("Recorded cost", moneyExact(s.cost.recorded));
    if (s.cost.estimated_total && s.cost.estimated_total !== s.cost.recorded) row("Est. with missing trials", "~" + moneyExact(s.cost.estimated_total));
    if (s.walltimeHours) row("Trial walltime", Math.round(s.walltimeHours) + " h summed");
    ev.appendChild(dl);
    cols.appendChild(ev);

    box.appendChild(cols);
    return box;
  }

  function sources(m, run) {
    var box = el("div", "fb-sources");
    var jobs = el("div", "fb-sources__col");
    jobs.appendChild(el("h3", "", "Harbor jobs"));
    var ul = el("ul", "fb-joblist");
    run.jobs.forEach(function (j) {
      var li = el("li");
      li.appendChild(external(j.url, j.name));
      ul.appendChild(li);
    });
    jobs.appendChild(ul);
    if (!run.jobs.length) jobs.appendChild(el("p", "fb-scan__note", "None: sample data has no Harbor jobs."));
    if (run.source) {
      var p = el("p");
      p.appendChild(external(run.source, run.tier === "ours" ? "Submission pull request" : "Leaderboard submission"));
      jobs.appendChild(p);
    }
    box.appendChild(jobs);
    var notes = el("div", "fb-sources__col");
    notes.appendChild(el("h3", "", "Accounting"));
    var nl = el("ul", "fb-notes");
    var lines = run.notes.slice();
    if (run.cost.pricing) lines.unshift(m.data.pricing[run.cost.pricing].note);
    if (run.cost.basis === "published leaderboard total" && run.cost.recorded !== run.cost.published) {
      lines.unshift("Cost shown is the published total (" + moneyExact(run.cost.published) + "); the public Hub job records " + moneyExact(run.cost.recorded) + " over " + run.cost.coverage + " trials.");
    }
    run.excluded.forEach(function (x) {
      lines.push("Excluded trial " + x.id.slice(0, 8) + " (" + x.task + "): " + x.reason);
    });
    if (!run.reconciled) lines.unshift("Not fully reconciled with the submitted trial set; treat the cells as indicative.");
    lines.forEach(function (n) {
      nl.appendChild(el("li", "", n));
    });
    notes.appendChild(nl);
    box.appendChild(notes);
    return box;
  }

  /* ── Compare page ──────────────────────────────────────────────────── */
  function renderCompare(root, data) {
    var params = new URLSearchParams(window.location.search);
    var cid = params.get("c");
    var comparison = data.comparisons.filter(function (c) {
      return c.id === cid;
    })[0];
    if (!comparison && !params.get("a")) comparison = data.comparisons[0];
    var first = model(data).byId[comparison ? comparison.a || (comparison.pairs ? comparison.pairs[0][0] : comparison.runs[0]) : params.get("a")];
    var m = model(data, first ? first.benchmark : null);

    var tabs = el("nav", "fb-cmp-tabs");
    tabs.setAttribute("aria-label", "Comparisons");
    m.data.comparisons.forEach(function (c) {
      var a = link(BENCH_ROOT + "compare/?c=" + c.id, "fb-cmp-tab", c.title);
      if (comparison && comparison.id === c.id) a.setAttribute("aria-current", "page");
      tabs.appendChild(a);
    });
    var custom = link(BENCH_ROOT + "compare/?a=" + m.runs[0].id + "&b=" + m.runs[m.runs.length - 1].id, "fb-cmp-tab fb-cmp-tab--custom", "Pick your own");
    if (!comparison) custom.setAttribute("aria-current", "page");
    tabs.appendChild(custom);
    root.appendChild(tabs);

    if (comparison && comparison.kind === "pairs") return renderPairs(root, m, comparison);
    if (comparison && comparison.kind === "set") return renderSet(root, m, comparison);
    var a = m.byId[comparison ? comparison.a : params.get("a")] || m.runs[0];
    var b = m.byId[comparison ? comparison.b : params.get("b")] || m.runs[1];
    renderH2H(root, m, a, b, comparison);
  }

  function pickers(m, a, b) {
    var bar = el("div", "fb-pickers");
    [a, b].forEach(function (cur, side) {
      var select = el("select", "fb-select");
      select.setAttribute("aria-label", side ? "Second run" : "First run");
      m.runs.concat(m.claims).forEach(function (e) {
        var o = el("option", "", (e.tier === "claim" ? e.source + " claim" : e.harness) + " · " + title(e) + (e.timeout === "6h" ? " (6h)" : "") + (e.sample ? " (sample)" : ""));
        o.value = e.id;
        o.selected = e.id === cur.id;
        select.appendChild(o);
      });
      select.addEventListener("change", function () {
        var ids = side ? [a.id, select.value] : [select.value, b.id];
        window.location.href = compareHref(ids[0], ids[1]);
      });
      bar.appendChild(select);
      if (!side) bar.appendChild(el("span", "fb-vs", "vs"));
    });
    return bar;
  }

  function compareHeader(m, comparison) {
    var h = el("header", "fb-cmp-head");
    h.appendChild(el("p", "fb-kicker", { pairs: "Claims vs receipts", h2h: "Head to head", set: "Series" }[comparison.kind]));
    h.appendChild(el("h1", "", comparison.title));
    h.appendChild(el("p", "fb-lede", comparison.claim));
    if (comparison.caveat) h.appendChild(el("p", "fb-caveat", comparison.caveat));
    return h;
  }

  function sideCard(m, e, cls) {
    var card = el(e.tier === "claim" ? "div" : "a", "fb-side " + cls + " fb-side--" + e.tier);
    if (e.tier !== "claim") card.href = runHref(e.id);
    var top = el("div", "fb-side__top");
    top.appendChild(familyMark(m, e.family));
    var n = el("div");
    n.appendChild(el("span", "fb-model", title(e)));
    var meta = el("span", "fb-meta");
    meta.appendChild(tierBadge(e));
    meta.appendChild(el("span", "fb-harness", harnessLine(e)));
    n.appendChild(meta);
    top.appendChild(n);
    card.appendChild(top);
    var nums = el("div", "fb-side__nums");
    var s = el("div");
    s.appendChild(el("span", "fb-side__v", pct(e.score)));
    s.appendChild(el("span", "fb-side__k", e.tier === "claim" ? "reported score" : e.passes + " of " + e.slots + " passed"));
    nums.appendChild(s);
    var c = el("div");
    c.appendChild(el("span", "fb-side__v", costText(e, true)));
    c.appendChild(el("span", "fb-side__k", "per run · " + moneyExact(e.cost.total / (e.slots || 445)) + " per trial"));
    nums.appendChild(c);
    card.appendChild(nums);
    return card;
  }

  function renderH2H(root, m, a, b, comparison) {
    if (a.sample || b.sample) root.appendChild(sampleBanner());
    if (comparison) root.appendChild(compareHeader(m, comparison));
    else {
      var h = el("header", "fb-cmp-head");
      h.appendChild(el("p", "fb-kicker", "Head to head"));
      h.appendChild(el("h1", "", "Pick any two."));
      root.appendChild(h);
    }
    root.appendChild(pickers(m, a, b));

    var duo = el("div", "fb-duo");
    duo.appendChild(sideCard(m, a, "fb-side--a"));
    var delta = el("div", "fb-delta");
    delta.appendChild(el("span", "fb-delta__v", pts(a.score - b.score)));
    delta.appendChild(el("span", "fb-delta__k", "score"));
    var ratio = a.cost.total / b.cost.total;
    delta.appendChild(el("span", "fb-delta__v", ratio < 1 ? Math.floor((1 - ratio) * 100) + "% less" : "×" + ratio.toFixed(2)));
    delta.appendChild(el("span", "fb-delta__k", "cost per run"));
    duo.appendChild(delta);
    duo.appendChild(sideCard(m, b, "fb-side--b"));
    root.appendChild(duo);

    if (a.tier === "claim" || b.tier === "claim") {
      var note = el("div", "fb-callout");
      note.appendChild(el("strong", "", "One side is a claim."));
      note.appendChild(el("span", "", " " + (a.tier === "claim" ? a : b).note + " Task-level comparison needs trial data on both sides."));
      root.appendChild(note);
      return;
    }

    root.appendChild(sectionHead("Task by task", "Where the points come from.", "Each column is one task: " + harnessLabel(a) + " passes rise above the line, " + harnessLabel(b) + " passes hang below. Sorted by the difference."));
    root.appendChild(butterfly(m, a, b));
  }
  function harnessLabel(e) {
    return e.harness + " · " + e.model.replace("GPT-5.6 ", "") + " " + e.effort;
  }

  function butterfly(m, a, b) {
    var items = m.tasks.map(function (name, ti) {
      var pa = taskPasses(a, ti, m.attempts);
      var pb = taskPasses(b, ti, m.attempts);
      return { name: name, ti: ti, a: pa, b: pb, d: pa - pb };
    });
    items.sort(function (x, y) {
      return y.d - x.d || y.a + y.b - (x.a + x.b) || (x.name < y.name ? -1 : 1);
    });
    var cw = Math.max(10, Math.floor(760 / items.length));
    var ch = Math.min(cw * 0.9, 16);
    var W = items.length * cw;
    var mid = 5 * ch + 12;
    var labels = items.length <= 40 ? 170 : 0;
    var padL = labels ? 110 : 0;
    var H = mid * 2 + labels;
    var root = svg("svg", { class: "fb-butterfly" + (items.length < 40 ? " fb-butterfly--wide" : ""), viewBox: -padL + " 0 " + (W + padL) + " " + H, role: "img", "aria-label": "Per-task passes, " + harnessLabel(a) + " above, " + harnessLabel(b) + " below" });
    var aWins = 0;
    var bWins = 0;
    items.forEach(function (it, col) {
      var x = col * cw;
      if (it.d > 0) aWins++;
      if (it.d < 0) bWins++;
      if (it.d !== 0) svg("rect", { x: x - 0.5, y: 0, width: cw, height: mid * 2, class: it.d > 0 ? "fb-bf-win fb-bf-win--a" : "fb-bf-win fb-bf-win--b" }, root);
      var aa = attemptsOf(a, it.ti, m.attempts);
      var bb = attemptsOf(b, it.ti, m.attempts);
      for (var i = 0; i < m.attempts; i++) {
        var pa = { c: i < it.a ? "1" : "0", s: i < it.a ? aa[i].s : "" };
        var pb = { c: i < it.b ? "1" : "0", s: i < it.b ? bb[i].s : "" };
        drawAttempt(root, x + 1, mid - 6 - (i + 1) * ch + 1, cw - 2, ch - 2, pa, i < it.a ? "fb-c fb-c--1 fb-tier-" + a.tier : "fb-c fb-c--0", 8);
        drawAttempt(root, x + 1, mid + 6 + i * ch + 1, cw - 2, ch - 2, pb, i < it.b ? "fb-c fb-c--1 fb-tier-" + b.tier + (a.tier === b.tier ? " fb-tier-alt" : "") : "fb-c fb-c--0", 8);
      }
    });
    svg("line", { x1: 0, x2: W, y1: mid, y2: mid, class: "fb-bf-axis" }, root);
    if (labels) {
      items.forEach(function (it, col) {
        var t = svg("text", { x: 0, y: 0, "text-anchor": "end", transform: "translate(" + (col * cw + cw / 2 + 3) + " " + (mid * 2 + 6) + ") rotate(-58)", class: "fb-taskhead__t" }, root);
        t.textContent = it.name;
      });
    }
    root.addEventListener("mousemove", function (evt) {
      var box = root.getBoundingClientRect();
      var col = Math.floor((((evt.clientX - box.left) / box.width) * (W + padL) - padL) / cw);
      var it = items[col];
      if (!it) return hideTip();
      showTip(evt, [it.name, harnessLabel(a) + ": " + it.a + " of " + m.attempts].concat(scanLines(a, it.ti, m.attempts), [harnessLabel(b) + ": " + it.b + " of " + m.attempts], scanLines(b, it.ti, m.attempts)));
    });
    root.addEventListener("mouseleave", hideTip);

    var fig = el("figure", "fb-figure fb-figure--bf");
    var tally = el("div", "fb-tally");
    function t(v, k, cls) {
      var d = el("div", cls);
      d.appendChild(el("span", "fb-tally__v", String(v)));
      d.appendChild(el("span", "fb-tally__k", k));
      tally.appendChild(d);
    }
    t(aWins, "tasks where " + harnessLabel(a) + " passed more attempts", "fb-tally--a");
    t(items.length - aWins - bWins, "tasks tied", "");
    t(bWins, "tasks where " + harnessLabel(b) + " passed more", "fb-tally--b");
    fig.appendChild(tally);
    var sc = el("div", "fb-scroll");
    sc.appendChild(root);
    fig.appendChild(sc);

    var swings = items
      .filter(function (it) {
        return Math.abs(it.d) >= 3;
      })
      .slice(0, 12);
    if (swings.length) {
      var list = el("ul", "fb-swings");
      swings.forEach(function (it) {
        var li = el("li", it.d > 0 ? "is-a" : "is-b");
        li.appendChild(el("span", "fb-mono", it.name));
        li.appendChild(el("span", "", it.a + "–" + it.b));
        list.appendChild(li);
      });
      var cap = el("figcaption", "fb-caption");
      cap.appendChild(el("span", "", "Biggest swings (attempts passed, " + harnessLabel(a) + " first):"));
      fig.appendChild(cap);
      fig.appendChild(list);
    }
    return fig;
  }

  function renderPairs(root, m, comparison) {
    root.appendChild(compareHeader(m, comparison));
    var table = el("div", "fb-pairs");
    var head = el("div", "fb-pairs__head");
    ["Setting", "Score", "Cost per task"].forEach(function (h) {
      head.appendChild(el("span", "", h));
    });
    table.appendChild(head);
    var sMin = 70;
    var sMax = 92;
    var cMax = 1;
    comparison.pairs.forEach(function (pair) {
      var ours = m.byId[pair[0]];
      var claim = m.byId[pair[1]];
      var row = el("div", "fb-pairs__row");
      var who = el("div", "fb-who");
      who.appendChild(familyMark(m, ours.family));
      var nm = el("span", "fb-names");
      nm.appendChild(el("span", "fb-model", title(ours)));
      var links = el("span", "fb-meta");
      links.appendChild(link(runHref(ours.id), "", "our run"));
      links.appendChild(external(claim.url, claim.source));
      nm.appendChild(links);
      who.appendChild(nm);
      row.appendChild(who);
      row.appendChild(dumbbell(claim.score, ours.score, sMin, sMax, pct, pts(ours.score - claim.score), "Score"));
      var oc = ours.cost.total / ours.slots;
      var cc = claim.cost.perTask;
      row.appendChild(dumbbell(cc, oc, 0, cMax, function (v) { return "$" + v.toFixed(2); }, Math.floor((1 - oc / cc) * 100) + "% less", "Cost per task"));
      table.appendChild(row);
    });
    root.appendChild(table);
    var lg = el("div", "fb-legend");
    [["fb-sw fb-sw--ours", "fast-agent, 445 trials"], ["fb-sw fb-sw--claim", "vendor figure, no trials"]].forEach(function (i) {
      var s = el("span", "fb-legend__i");
      s.appendChild(el("i", i[0]));
      s.appendChild(el("span", "", i[1]));
      lg.appendChild(s);
    });
    root.appendChild(lg);
    var notes = el("ul", "fb-notes");
    comparison.pairs.forEach(function (pair) {
      var claim = m.byId[pair[1]];
      notes.appendChild(el("li", "", title(claim) + ": " + claim.note + (claim.cost.estimate ? " Cost shown at " + m.data.pricing[claim.pricing].label + " (was $" + claim.cost.original.toFixed(2) + " per task)." : "")));
    });
    root.appendChild(notes);
  }

  function dumbbell(from, to, min, max, fmt, deltaText, label) {
    var box = el("div", "fb-dumbbell");
    box.dataset.k = label;
    var track = el("div", "fb-dumbbell__track");
    var pos = function (v) {
      return ((v - min) / (max - min)) * 100;
    };
    var lo = Math.min(from, to);
    var hi = Math.max(from, to);
    var span = el("i", "fb-dumbbell__span");
    span.style.left = pos(lo) + "%";
    span.style.width = pos(hi) - pos(lo) + "%";
    track.appendChild(span);
    var c = el("b", "fb-dumbbell__claim");
    c.style.left = pos(from) + "%";
    c.dataset.label = fmt(from);
    var o = el("b", "fb-dumbbell__ours");
    o.style.left = pos(to) + "%";
    o.dataset.label = fmt(to);
    track.appendChild(c);
    track.appendChild(o);
    box.appendChild(track);
    box.appendChild(el("span", "fb-dumbbell__d", deltaText));
    return box;
  }

  function renderSet(root, m, comparison) {
    root.appendChild(compareHeader(m, comparison));
    if (comparison.runs.some(function (id) { return m.byId[id].sample; })) root.appendChild(sampleBanner());
    var runs = comparison.runs.map(function (id) {
      return m.byId[id];
    });
    root.appendChild(posterCard(m, runs, m.bench.name, comparison.caveat));
  }

  /* ── Poster card (Direction C) ─────────────────────────────────────── */
  function posterCard(m, runs, heading, footnote) {
    var card = el("article", "fb-poster");
    var head = el("header", "fb-poster__head");
    head.appendChild(el("h2", "", heading));
    head.appendChild(el("p", "", (heading === m.bench.name ? "" : m.bench.name + " · ") + m.bench.taskLabel + " · total cost per run"));
    card.appendChild(head);
    var body = el("div", "fb-poster__body");
    var rows = el("div", "fb-poster__rows");
    var cMax = Math.max.apply(null, runs.map(function (r) { return r.cost.total; }));
    runs.forEach(function (r) {
      var row = el(r.tier === "claim" ? "div" : "a", "fb-poster__row fb-poster__row--" + r.tier);
      if (r.tier !== "claim") row.href = runHref(r.id);
      var who = el("div", "fb-who");
      who.appendChild(familyMark(m, r.family, "lg"));
      var nm = el("div", "fb-names");
      nm.appendChild(el("span", "fb-poster__name", r.tier === "claim" ? r.source : r.harness));
      nm.appendChild(el("span", "fb-poster__model", title(r)));
      nm.appendChild(el("span", "fb-poster__meta", r.tier === "claim" ? "as published, no trials" : (r.harnessVersion ? "v" + r.harnessVersion + " · " : "") + r.passes + "/" + r.slots + " passed" + (r.sample ? " · SAMPLE" : "")));
      who.appendChild(nm);
      row.appendChild(who);
      var waffle = el("div", "fb-poster__waffle");
      waffle.appendChild(r.tier === "claim" ? claimStrip(m, r, { cell: 3.45, height: 62 }) : sortedWaffle(m, r));
      row.appendChild(waffle);
      row.appendChild(el("span", "fb-poster__score", pct(r.score)));
      var cost = el("div", "fb-poster__cost");
      var bar = el("span", "fb-poster__bar");
      var fill = el("i");
      fill.style.width = (r.cost.total / cMax) * 100 + "%";
      bar.appendChild(fill);
      cost.appendChild(bar);
      cost.appendChild(el("span", "fb-poster__money", costText(r, true)));
      row.appendChild(cost);
      rows.appendChild(row);
    });
    body.appendChild(rows);
    card.appendChild(body);
    card.appendChild(legend(runs.filter(function (r) { return r.tier !== "claim"; }), runs.some(function (r) { return r.tier === "claim"; })));
    card.appendChild(el("p", "fb-poster__foot", footnote || ""));
    return card;
  }

  /* 445 attempts, passes first, filled column by column (read like the harness charts). */
  function sortedWaffle(m, run) {
    var codes = [];
    for (var t = 0; t < m.tasks.length; t++) codes = codes.concat(attemptsOf(run, t, m.attempts));
    codes.sort(function (a, b) {
      return CELL_ORDER[a.c] - CELL_ORDER[b.c] || isFlagged(a.s) - isFlagged(b.s) || isFallback(a.s) - isFallback(b.s);
    });
    var rowsN = codes.length > 200 ? 9 : 5;
    var colsN = Math.ceil(codes.length / rowsN);
    var cell = 6;
    var W = colsN * (cell + 1);
    var H = rowsN * (cell + 1);
    var root = svg("svg", { class: "fb-strip fb-strip--" + run.tier, viewBox: "0 0 " + W + " " + H, role: "img", "aria-label": run.passes + " of " + run.slots + " passed" });
    codes.forEach(function (att, i) {
      var col = Math.floor(i / rowsN);
      var row = i % rowsN;
      drawAttempt(root, col * (cell + 1), row * (cell + 1), cell, cell, att, cellClass(att.c), 6);
    });
    return root;
  }

  /* ── Boot ──────────────────────────────────────────────────────────── */
  function renderCalibration(root, data) {
    // Methodology pages have a text-width column; a narrower viewBox keeps labels legible.
    root.appendChild(calibration(model(data, root.dataset.bench), { width: 700, height: 420 }));
  }

  var RENDERERS = { index: renderIndex, run: renderRun, compare: renderCompare, calibration: renderCalibration };

  function start() {
    if (!window.faBench) return;
    document.querySelectorAll("[data-fa-bench]").forEach(function (root) {
      if (root.dataset.faBenchReady === window.location.href) return;
      root.dataset.faBenchReady = window.location.href;
      root.innerHTML = "";
      root.classList.add("fb");
      RENDERERS[root.dataset.faBench](root, window.faBench);
    });
  }

  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", start);
  else start();
  if (window.document$ && window.document$.subscribe) window.document$.subscribe(start);
})();
